import { Button } from '@refy-design/web';
import { Direction } from '@refy-design/web';
import { Input } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function DirectionExample() {
  const [dir, setDir] = useState<'ltr' | 'rtl'>('ltr');
  return (
    <div style={stack}>
      <div>
        <Button onClick={() => setDir('ltr')} aria-pressed={dir === 'ltr'}>
          Left to right
        </Button>
        <Button onClick={() => setDir('rtl')} aria-pressed={dir === 'rtl'}>
          Right to left
        </Button>
      </div>
      <Direction dir={dir}>
        <p>Home / Library / Material</p>
        <Input label="Material name" placeholder="Write a name" />
      </Direction>
    </div>
  );
}
export function Example() {
  return <DirectionExample />;
}
